1. Create a class that represents your matrix:
```cpp
class Matrix {
public:
    Matrix(int rows, int columns) : rows_(rows), columns_(columns) {
        data_ = new int[rows * columns];
    }

    ~Matrix() {
        delete[] data_;
    }

    int get(int row, int column) const {
        return data_[row * columns + column];
    }

    void set(int row, int column, int value) {
        data_[row * columns + column] = value;
    }

    int rows() const { return rows_; }
    int columns() const { return columns_; }

private:
    int* data_;
    int rows_;
    int columns_;
};
```
1. Create a class that displays the matrix as a bitmap:
```cpp
class MatrixBitmap : public QWidget {
public:
    MatrixBitmap(Matrix& matrix, int width, int height) : matrix_(matrix), width_(width), height_(height) {
        setMinimumSize(width, height);
        setMaximumSize(width, height);
    }

    void paintEvent(QPaintEvent* event) override {
        QPainter painter(this);
        painter.setRenderHint(QPainter::Antialiasing);

        int scale = std::min(width_, height_) / matrix_.rows();
        QMatrix matrix;
        matrix.scale(scale, scale);

        for (int i = 0; i < matrix_.rows(); ++i) {
            for (int j = 0; j < matrix_.columns(); ++j) {
                int value = matrix_.get(i, j);
                QColor color(value * 255, value * 255, value * 255);
                painter.setBrush(color);
                painter.drawRect(i * scale, j * scale, scale - 1, scale - 1);
            }
        }
    }

