Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <vector>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, num3, count;

    cout << "Enter the first two numbers of the Fibonacci sequence: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> num1 >> num2;

    if (num1 < 0 || num2 < 0) {
        cout << "Error: Both numbers must be non-negative." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> count;

    if (count < 0) {
        cout << "Error: The number of sequence elements must be non-negative." << endl;
        return 1;
    }

    vector<int> sequence(count);
    sequence[0] = num1;
    sequence[1] = num2;

    for (int i = 2; i < count; i++) {
        sequence[i] = fibonacci(i, num1, num2);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < count; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

