import requests
from bs4 import BeautifulSoup
import os

def download_photo(url, filename):
    response = requests.get(url, stream=True)
    if response.status_code == 200:
        with open(filename, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
        print(f"Downloaded {filename}")
    else:
        print(f"Error downloading {filename}: {response.status_code}")

def download_album_photos(album_link):
    response = requests.get(album_link)
    soup = BeautifulSoup(response.text, 'html.parser')

    photo_links = []
    for div in soup.find_all('div', class_='gallery-item'):
        photo_links.append(div.find('img')['src'])

    for i, link in enumerate(photo_links):
        filename = f"photo_{i}.jpg"
        download_photo(link, filename)

if __name__ == "__main__":
    album_link = "https://photos.google.com/share/AF1QipN_1YzG54rMhXyZCkpI_4KdFuHmRU5jb3JpZ2luX2Vjb25kbGVkLmNsb3VkLmlvbXA6YW1lcyw?key=0ByD_OXxJcVtqb3JpZ2luX2Vjb25kbGVkLmNsb3VkLmlvbXA6YW1lcyw"
