```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A2:A"); // Assuming your place names are in column A starting from row 2
  var placeNames = dataRange.getValues().flat();

  var geocoder = new google.maps.Geocoder();
  for (var i = 0; i < placeNames.length; i++) {
    geocoder.geocode({ address: placeNames[i] }, function(results, status) {
      if (status == google.maps.GeocoderStatus.OK) {
        var latitude = results[0].geometry.location.lat();
        var longitude = results[0].geometry.location.lng();

        sheet.getRange("B" + (i + 1)).setValue(latitude);
        sheet.getRange("C" + (i + 1)).setValue(longitude);
      } else {
        console.error("Error geocoding " + placeNames[i] + ": " + status);
      }
    });
  }
}
```

This script will loop through each place name in column A and use the Google Maps Geocoder API to get its latitude and longitude. The results will be stored in columns B and C respectively, starting from row 3.

