```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"
)

type StructInfo struct {
	Name     string
	Fields   []FieldInfo
}

type FieldInfo struct {
	Name    string
	Type    string
	Default interface{}
}

func parseGoSource(file string, structName string) (StructInfo, error) {
	data, err := ioutil.ReadFile(file)
	if err != nil {
		return StructInfo{}, fmt.Errorf("error reading %s: %w", file, err)
	}

	reg, err := regexp.Compile(`(?m)struct\s+(\w+)\s*{`)
	if err != nil {
		return StructInfo{}, fmt.Errorf("error compiling regex: %w", err)
	}

	matches := reg.FindStringSubmatch(string(data))
	if len(matches) != 2 {
		return StructInfo{}, fmt.Errorf("error parsing struct definition")
	}

	name := matches[1]
	if name != structName {
		return StructInfo{}, fmt.Errorf("incorrect struct name")
	}

	fields := []FieldInfo{}
	reg = regexp.MustCompile(`(?m)(\w+)\s+(\w+)\s*(?:\s*(\w+))?`)
	for _, line := range strings.Split(string(data), "\n") {
		matches := reg.FindStringSubmatch(line)
		if len(matches) == 3 {
			fieldName := matches[1]
			fieldType := matches[2]
			defaultValue := ""
			if len(matches) == 4 {
				defaultValue = matches[3]
			}
			fields = append(fields, FieldInfo{Name: fieldName, Type: fieldType, Default: defaultValue})
		}
	}

	return StructInfo{Name: name, Fields: fields}, nil

