    if rabbit.furColor == 'brown'
        survivalProbability = 0.8;
    else
        survivalProbability = 0.4;
    end
    % Calculate the rabbit's fitness as the product of its survival probability and its age
    fitness = survivalProbability * rabbit.age;
end
% Define a function to select the fittest rabbits
function selectedRabbits = selectFittest(rabbits, numSelected)
    % Sort the rabbits by their fitness in descending order
    [fitnessScores, sortedIndices] = sort(calcFitness(rabbits), 'descend');
    % Select the top numSelected rabbits
    selectedRabbits = rabbits(sortedIndices(1:numSelected));
end
% Define a function to simulate natural selection
function evolvePopulation(population, numGenerations, numSelected)
    % Initialize the next generation
    nextGeneration = [];
    % Loop over generations
    for i = 1:numGenerations
        % Select the fittest rabbits
        selectedRabbits = selectFittest(population, numSelected);
        % Add the selected rabbits to the next generation
        nextGeneration = [nextGeneration, selectedRabbits];
        % Remove the selected rabbits from the current generation
        population = population(~ismember(population.ID, selectedRabbits.ID));
    end
    % Return the final generation
    return nextGeneration;
end
