```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    char *cstring = (char *)malloc(sizeof(char) * (argc + 1));

    for (int i = 0; i < argc; i++) {
        strcat(cstring, argv[i]);
        if (i != argc - 1) {
            strcat(cstring, " ");
        }
    }

    printf("C string: %s\n", cstring);

    free(cstring);

    return 0;
}
```

