Here's a simple example of a toast notification using React context:

```jsx
import React, { createContext, useState } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toast, setToast] = useState(null);

  function showToast(message) {
    setToast({ message, visible: true });
  }

  function hideToast() {
    setToast({ ...toast, visible: false });
  }

  return (
    <ToastContext.Provider value={{ toast, showToast, hideToast }}>
      {children}
    </ToastContext.Provider>
  );
}

function ToastConsumer() {
  const { toast, showToast, hideToast } = useContext(ToastContext);

  if (toast && toast.visible) {
    return (
      <div className="toast">
        {toast.message}
        <button onClick={hideToast}>Close</button>
      </div>
    );
  }

  return null;
}

function App() {
  return (
    <ToastProvider>
      <ToastConsumer />
    </ToastProvider>
  );
}

export default App;
```

In this example, we have a `ToastProvider` component that creates a context and manages the toast state. The `ToastConsumer` component consumes the context and renders the toast if it's visible. The `showToast` and `hideToast` functions are used to display and hide the toast, respectively.

