JavaScript Code (script.js):
```javascript
function calculateProduct() {
    const primeNumbers = document.getElementById('primeNumbers');
    const numbers = [];

    primeNumbers.querySelectorAll('li').forEach(li => {
        numbers.push(parseInt(li.textContent));
    });

