```typescript
function generateBarChart(data: number[]) {
  const chartWidth = 400;
  const chartHeight = 200;
  const barWidth = 20;
  const barSpacing = 5;
  const barColors = ['#4CAF50', '#F44336', '#2196F3', '#95A5A6', '#FFC107'];

  const canvas = document.createElement('canvas');
  canvas.width = chartWidth;
  canvas.height = chartHeight;

  const ctx = canvas.getContext('2d');

  // Calculate the position of each bar
  const barPositions = data.map((value, index) => {
    return {
      x: index * (barWidth + barSpacing),
      y: chartHeight - value * barWidth / 100
    };
  });

  // Draw the bars
  barColors.forEach((color, index) => {
    ctx.fillStyle = color;
    ctx.fillRect(barPositions[index].x, barPositions[index].y, barWidth, barWidth);
  });

  return canvas;
}

const data = [10, 20, 30, 40, 50];
const chart = generateBarChart(data);
document.body.appendChild(chart);
